rows = []


def add(
    name,
    year,
    mit_url,
    high_school,
    hs_grad_year,
    category,
    subcategory,
    level,
    achievement,
    evidence_url,
    *extra_sources,
    confidence="high",
    debate="no_documented",
    debate_details=None,
):
    sources = []
    for url in (mit_url, evidence_url, *extra_sources):
        if url and url not in sources:
            sources.append(url)
    if "mitathletics.com" in mit_url:
        source_frame = "MIT athletics roster"
    elif any(host in mit_url for host in ("rocketry.mit.edu", "wikis.mit.edu", "sigmakappa.mit.edu", "axo.mit.edu", "mit.pibetaphi.org", "pkt.mit.edu", "phidelts.mit.edu")):
        source_frame = "MIT student organization roster"
    elif "calendar.mit.edu" in mit_url:
        source_frame = "MIT event biography"
    else:
        source_frame = "MIT student biography or team page"
    confidence_note = (
        " Medium confidence reflects a weaker public identity linkage or less specific activity evidence."
        if confidence == "medium"
        else ""
    )
    rows.append(
        {
            "record_type": "mit_student",
            "person_name": name,
            "mit_status": "current_undergrad",
            "mit_class_year": year,
            "mit_evidence_url": mit_url,
            "high_school": high_school,
            "hs_grad_year": hs_grad_year,
            "activities": [
                {
                    "category": category,
                    "subcategory": subcategory,
                    "level": level,
                    "achievement": achievement,
                    "evidence_url": evidence_url,
                }
            ],
            "flagship_category": category,
            "flagship_signal": achievement,
            "flagship_confidence": confidence,
            "debate": debate,
            "debate_details": debate_details,
            "source_urls": sources,
            "notes": f"Sampling frame: {source_frame}. MIT status/class year and a pre-college activity were corroborated from the cited public sources.{confidence_note} No contact details were collected.",
        }
    )


